function leaveRoom(reportID: string, shouldShowConfirmation: boolean) {
    const report = ReportConnection.getReport(reportID);
    const isOnAppScapeFlow = report?.policyID && PolicyActions.isPendingApprover(report.policyID);

    if (shouldShowConfirmation || isOnAppScapeFlow) {
        let confirmationTitle = '';
        if (isOnAppScapeFlow) {
            confirmationTitle = Localize.translate('violations.leaveWorkspaceAndAppscape.title');
        } else if (ReportUtils.isLastMember(report)) {
            confirmationTitle = Localize.translate('common.areYouSure');
        }

        let confirmationText = '';
        if (isOnAppScapeFlow) {
            confirmationText = Localize.translate('violations.leaveWorkspaceAndAppscape.description');
        } else if (ReportUtils.isLastMember(report)) {
            confirmationText = Localize.translate('report.aboutToLeaveOnlyMember');
        } else {
            confirmationText = Localize.translate(LEAVE_ROOM_CONFIRMATION_TYPE[report?.visibility ?? '']);
        }
        Modal.show(
            ReportUtils.getReportName(report),
            confirmationText,
            [
                {
                    text: Localize.translate('common.cancel'),
                    onPress: () => Modal.close(),
                    style: 'cancel',
                },
                {
                    text: Localize.translate('common.leave'),
                    onPress: () => {
                        Modal.close();
                        if (isOnAppScapeFlow) {
                            PolicyActions.removeSelfFromWorkspace(report.policyID);
                            return;
                        }
                        performLeaveRoom(reportID);
                    },
                    style: 'danger',
                },
            ],
            undefined,
            undefined,
            confirmationTitle,
        );
        return;
    }

    performLeaveRoom(reportID);
}
