        reportID,
    };

    API.write(WRITE_COMMANDS.LEAVE_ROOM, parameters, {
        optimisticData,
        successData,
        failureData,
    });

    if (report?.chatType === CONST.REPORT.CHAT_TYPE.POLICY_ROOM) {
        unsubscribeFromLeavingRoomReportChannel(reportID);
    }
}
